<script setup lang="ts">
import type { Checkin, Workout, StrengthWorkout } from '../api'
defineProps<{checkins:Checkin[];runs:Workout[];strength:StrengthWorkout[];timezone:string}>()
const phases:Record<string,string>={unknown:'时机未确定',before:'训练前',during:'训练中',after:'训练后',next_day:'次日'}
const readiness:Record<string,string>={unknown:'尚不确定',ready:'希望常规安排',reduce:'希望减量',rest:'希望休息'}
function when(c:Checkin,timezone:string){return c.observed_at?new Date(c.observed_at).toLocaleString('zh-CN',{timeZone:c.observation_timezone||timezone}):'发生时间未填写'}
</script>
<template><section class="card panelwide feedback-history"><div class="sectionhead"><h2>身体反馈时间线</h2><span class="tiny muted">{{checkins.length}} 条 · 疲劳、酸胀与疼痛分开记录</span></div><p v-if="!checkins.length" class="empty">还没有身体反馈。</p><article v-for="c in checkins.slice(0,20)" :key="c.id" class="checkin-note"><div class="row"><b>{{c.date}} · {{phases[c.feedback_phase]||'时机未确定'}}</b><span class="badge">{{readiness[c.training_readiness]}}</span></div><p class="tiny muted">{{when(c,timezone)}} · {{c.observation_timezone||timezone}}<template v-if="!c.observation_timezone">（原时区未记录，按当前档案时区查看）</template></p><p v-if="c.related_training_id" class="tiny">关联{{c.related_training_type==='run'?'跑步':'力量'}}：{{(c.related_training_type==='run'?runs:strength).find(r=>r.id===c.related_training_id)?.title||'已保存训练记录'}}</p><div class="feedback-values"><span>整体疲劳 {{c.fatigue}} / 10</span><span>肌肉酸胀 {{c.soreness_level??'未知'}} / 10 · {{c.soreness_location||'部位未填写'}}</span><span>疼痛 {{c.pain_level??'未知'}} / 10 · {{c.pain_location||'部位未填写'}}</span></div><p class="tiny muted">日常活动：{{c.function_affected===null?'未知':c.function_affected?'受影响':'未受影响'}}<template v-if="c.sleep_hours!==null"> · 睡眠 {{c.sleep_hours}} 小时</template></p><p v-if="c.illness_notes" class="tiny">疾病或身体变化：{{c.illness_notes}}</p><p v-if="c.notes" class="tiny muted">{{c.notes}}</p></article><p v-if="checkins.length>20" class="tiny muted">显示最近 20 条反馈。</p></section></template>
